class posix_state final:public kp::state_backend{public:posix_state(std::filesystem::path s,std::filesystem::path a,std::filesystem::path r,std::filesystem::path approvals):state_(std::move(s)),audit_(std::move(a)),rev_(std::move(r)),approvals_(std::move(approvals)){std::filesystem::create_directories(state_.parent_path());fd_=::open(state_.c_str(),O_RDWR|O_CREAT|O_CLOEXEC,0600);if(fd_<0||::fchmod(fd_,0600)!=0||::flock(fd_,LOCK_EX|LOCK_NB)!=0)throw std::runtime_error("state_lock_failed");load();++generation_;append("GENERATION\t"+std::to_string(generation_));}~posix_state()override{if(fd_>=0){::flock(fd_,LOCK_UN);::close(fd_);}}
