void handle_peer(xpc_connection_t peer,std::shared_ptr<context>ctx){const bool desktop=peer_matches_requirement(peer,ctx->cfg.desktop_requirement);const bool worker=peer_matches_requirement(peer,ctx->cfg.worker_requirement);if(!desktop&&!worker){xpc_connection_cancel(peer);return;}xpc_connection_set_event_handler(peer,^(xpc_object_t event){if(xpc_get_type(event)!=XPC_TYPE_DICTIONARY)return;const void*bytes=nullptr;size_t size=0;bytes=xpc_dictionary_get_data(event,"request",&size);if(!bytes||size==0||size>static_cast<size_t>(ctx->core_cfg.max_request_bytes)){reply(event,peer,kp::json::canonical(kp::denied_response("frame_size_invalid")));return;}try{pid_t pid=xpc_connection_get_pid(peer);uid_t uid=xpc_connection_get_euid(peer);au_asid_t asid=xpc_connection_get_asid(peer);auto request=kp::json::parse(std::string_view(static_cast<const char*>(bytes),size));kp::peer_identity identity{"macos",std::to_string(uid),"code-signing-requirement",worker?ctx->cfg.worker_requirement:ctx->cfg.desktop_requirement,std::to_string(asid),static_cast<std::uint64_t>(pid),desktop&&!worker,worker};if(worker){ctx->core.note_worker_denial(kp::json::required_string(request.as_object(),"behaviorSessionId"),identity,kp::json::required_string(request.as_object(),"workerIdentitySha256"));reply(event,peer,kp::json::canonical(kp::denied_response("worker_principal_denied")));return;}reply(event,peer,kp::json::canonical(ctx->core.handle(request,identity)));}catch(const std::exception&e){reply(event,peer,kp::json::canonical(kp::denied_response(e.what())));}});xpc_connection_activate(peer);}
int provision(const config&c,std::string&grant_hex,std::string&owner_hex){SecKeyRef key=load_or_create_key([NSString stringWithUTF8String:c.key_tag.c_str()],true);CFRelease(key);auto decode=[](std::string_view h){if(h.size()<32||h.size()%2)throw std::runtime_error("secret_hex_invalid");NSMutableData*d=[NSMutableData dataWithLength:h.size()/2];auto*out=static_cast<unsigned char*>(d.mutableBytes);for(std::size_t i=0;i<h.size()/2;++i){auto cv=[](char x)->int{if(x>='0'&&x<='9')return x-'0';if(x>='a'&&x<='f')return 10+x-'a';if(x>='A'&&x<='F')return 10+x-'A';return-1;};int a=cv(h[i*2]),b=cv(h[i*2+1]);if(a<0||b<0)throw std::runtime_error("secret_hex_invalid");out[i]=static_cast<unsigned char>((a<<4)|b);}return d;};@autoreleasepool{NSData*grant=decode(grant_hex);NSData*owner=decode(owner_hex);store_keychain_secret([NSString stringWithUTF8String:c.grant_service.c_str()],grant,c.service_binary);store_keychain_secret([NSString stringWithUTF8String:c.owner_service.c_str()],owner,c.service_binary);}std::fill(grant_hex.begin(),grant_hex.end(),'\0');std::fill(owner_hex.begin(),owner_hex.end(),'\0');return 0;}
