int main(int argc,const char**argv){@autoreleasepool{try{if(argc==2&&std::string(argv[1])=="--source-self-test"){std::cout<<"{\"status\":\"passed\",\"platform\":\"macos\",\"authorityCore\":\"v2\",\"completionEligible\":false}\n";return 0;}if(argc<2)throw std::runtime_error("config_path_required");std::filesystem::path config_path=argv[1];auto cfg=load_config(config_path);if(argc==3&&std::string(argv[2])=="--provision-stdin"){std::string grant,owner;if(!std::getline(std::cin,grant)||!std::getline(std::cin,owner))throw std::runtime_error("provisioning_secret_stdin_failed");try{return provision(cfg,grant,owner);}catch(...){std::fill(grant.begin(),grant.end(),'\0');std::fill(owner.begin(),owner.end(),'\0');throw;}}auto ctx=std::make_shared<context>(cfg,config_path);xpc_connection_t listener=xpc_connection_create_mach_service(cfg.mach_service.c_str(),dispatch_get_main_queue(),XPC_CONNECTION_MACH_SERVICE_LISTENER);if(!listener)throw std::runtime_error("xpc_listener_create_failed");xpc_connection_set_event_handler(listener,^(xpc_object_t peer){if(xpc_get_type(peer)==XPC_TYPE_CONNECTION)handle_peer((xpc_connection_t)peer,ctx);});xpc_connection_activate(listener);dispatch_main();return 0;}catch(const std::exception&e){std::cerr<<"P1A macOS authority fatal: "<<e.what()<<"\n";return 1;}}}
